with open("/workspace/DEMOS.json") as f:
    demos = json.load(f)

for d in demos:
    if d["task_id"] == "c118":
        print("=== c118 ROTATION ANALYSIS ===")
        for i in range(len(d["input_examples"])):
            inp = d["input_examples"][i]
            out = d["output_examples"][i]

            # Check if it's a left rotation
            if len(inp) == len(out) and inp:
                for rot in range(len(inp)):
                    rotated_left = inp[rot:] + inp[:rot]
                    if rotated_left == out:
                        print(f"  {inp} -> {out}: LEFT rotation by {rot}")
                        break
                else:
                    # Check right rotation
                    for rot in range(1, len(inp)+1):
                        rotated_right = inp[-rot:] + inp[:-rot]
                        if rotated_right == out:
                            print(f"  {inp} -> {out}: RIGHT rotation by {rot}")
                            break
                    else:
                        print(f"  {inp} -> {out}: NO ROTATION (identity or other)")
        break

